function renderRecords(rows){if(!Array.isArray(rows)||rows.length>100000)throw Error('Invalid historical annotation rows.');const host=q('#history-records'),table=document.createElement('table'),fields=[...new Set(rows.flatMap(r=>Object.keys(r)))],thead=document.createElement('thead'),tr=document.createElement('tr');for(const field of fields){const th=document.createElement('th');th.textContent=field;tr.append(th);}thead.append(tr);table.append(thead);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(const field of fields){const td=document.createElement('td');td.textContent=String(row[field]??'');td.title=td.textContent;tr.append(td);}body.append(tr);}table.append(body);host.replaceChildren(table);}
