q('#history-home').onclick=()=>save().then(()=>{H.token++;H.manifest=null;H.wave=null;H.records=null;H.files=null;q('#history-workspace').hidden=true;q('#home').hidden=false;q('#principles').hidden=false;}).catch(showError);
q('#history-prev').onclick=()=>{if(H.wave){H.start=Math.max(Math.min(...H.wave.t),H.start-Number(q('#history-span').value));plot();}};q('#history-next').onclick=()=>{if(H.wave){const n=Number(q('#history-span').value);H.start=Math.min(Math.max(Math.min(...H.wave.t),Math.max(...H.wave.t)-n),H.start+n);plot();}};q('#history-span').onchange=()=>{if(H.wave)H.start=Math.min(...H.wave.t);plot();};
