q('#history-save').onclick=()=>save().catch(showError);q('#history-backup').onclick=()=>snapshot().then(b=>download('ECG_'+H.reviewer+'_history.ecghistoryprogress',JSON.stringify(b))).catch(showError);q('#history-export').onclick=()=>exportPackage().catch(showError);q('#history-restore').onclick=()=>q('#history-backup-input').click();q('#history-backup-input').onchange=async e=>{try{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>50*1024*1024)throw Error('Backup is too large.');await restore(JSON.parse(await f.text()));}catch(e){showError(e);}};
